219: int addFiles(const char* dirname, const char* subPath) {
220:     DIR *dir;
221:     struct dirent *ent;
222:     bool error = false;
223:     std::string dirPath = dirname;
224:     dirPath += subPath;
225: 
226:     // Open directory
227:     if ((dir = opendir (dirPath.c_str())) != NULL) {
228: 
229:         // Read files from directory.
230:         while ((ent = readdir (dir)) != NULL) {
231: 
232:             // Ignore dir itself.
233:             if ((strcmp(ent->d_name, ".") == 0) || (strcmp(ent->d_name, "..") == 0)) {
234:                 continue;
235:             }
236: 
237:             if (!s_addAllFiles) {
238:                 bool skip = false;
239:                 size_t ignored_file_names_count = sizeof(ignored_file_names) / sizeof(ignored_file_names[0]);
240:                 for (size_t i = 0; i < ignored_file_names_count; ++i) {
241:                     if (strcmp(ent->d_name, ignored_file_names[i]) == 0) {
242:                         std::cerr << "skipping " << ent->d_name << std::endl;
243:                         skip = true;
244:                         break;
245:                     }
246:                 }
247:                 if (skip) {
248:                     continue;
249:                 }
250:             }
251: 
252:             std::string fullpath = dirPath;
253:             fullpath += ent->d_name;
254:             struct stat path_stat;
255:             stat (fullpath.c_str(), &path_stat);
256: 
257:             if (!S_ISREG(path_stat.st_mode)) {
258:                 // Check if path is a directory.
259:                 if (S_ISDIR(path_stat.st_mode)) {
260:                     // Prepare new sub path.
261:                     std::string newSubPath = subPath;
262:                     newSubPath += ent->d_name;
263:                     newSubPath += "/";
264: 
265:                     if (addFiles(dirname, newSubPath.c_str()) != 0)
