271:                 }
272:                 else
273:                 {
274:                     std::cerr << "skipping " << ent->d_name << std::endl;
275:                     continue;
276:                 }
277:             }
278: 
279:             // Filepath with dirname as root folder.
280:             std::string filepath = subPath;
281:             filepath += ent->d_name;
282:             std::cout << filepath << std::endl;
